mapper.select:
SELECT l.log_id AS log_id, l.account_id AS account_id, COALESCE(e.full_name, '系统') AS actor_name, COALESCE(u.role_code, 'SYSTEM') AS actor_role, l.action AS action, l.entity AS entity, l.entity_id AS entity_id, l.detail AS detail, l.ip AS ip, l.created_at AS created_at FROM audit_log l LEFT JOIN user_account u ON u.account_id = l.account_id LEFT JOIN employee e ON e.employee_id = u.employee_id
AND l.entity = #{entity}
AND l.entity_id = #{entityId}
ORDER BY l.log_id DESC LIMIT #{limit}
